def reference(x, n):
    # Obviously correct brute force: exists k >= 0 with n**k == x
    # Python ** semantics (so 0**0 == 1).
    for k in range(0, 500):
        try:
            p = pow(n, k)
        except Exception:
            continue
        if p == x:
            return True
        # abs grows monotonically for |n| >= 2, so we can stop
        if abs(n) >= 2 and abs(x) > 1 and abs(p) > abs(x):
            break
    return False

@given(
    x=st.integers(min_value=-200, max_value=2000),
    n=st.integers(min_value=-5, max_value=5),
)
def test_equivalence_to_reference_model(x, n):
    assert is_simple_power(x, n) is reference(x, n)
